// Authored content for 3.1.11.2 Species diversity (OxfordAQA 9610 v5.1, printed p.20; statements 3.1.11.2.s1–s5 in
// data/spec.js). The index of diversity is used exactly as the specification gives it: d = N(N − 1) / Σn(n − 1), with
// N = total number of organisms of all species and n = total number of organisms of each species. Every value of d on
// this page is computed by B.biodivModel.index (data/content/_biodiv-art.js) and was checked by hand (3.1.11 author
// report). All communities and farm data are ILLUSTRATIVE. Release review (2026-11-15, teacher's decision): material
// beyond the specification was removed: the UAE mangrove case study is now a short local example (no laws, planting
// statistics or area figures; the facts kept are from the Environment Agency – Abu Dhabi "Mangroves" page, checked
// 2026-11-04), and the Conservation Decision Challenge became ordinary page questions (two scenarios).
window.BIO = window.BIO || {}; window.BIO.content = window.BIO.content || {};
(function () {
  const A = window.BIO.biodivArt, M = window.BIO.biodivModel, CM = M.COMMUNITIES;
  const R = "3.1.11.2";
  const S = (...n) => n.map((k) => `${R}.s${k}`);
  const P = (slot) => window.BIO.views.photo(slot);
  const d2 = (counts) => M.fix(M.index(counts).d, 2);
  const D = (key) => M.dOf(key);
  const tbl = (rows, head = ["Species", "Number of individuals, n"]) => `<table class="tbl"><thead><tr>${head.map((h) => `<th>${h}</th>`).join("")}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((c) => `<td>${c}</td>`).join("")}</tr>`).join("")}</tbody></table>`;
  const comTable = (key) => tbl(CM[key].species);
  const ev = (rows) => `<ul class="small">${rows.map(([k, v]) => `<li>${k}: <strong>${v}</strong></li>`).join("")}</ul>`;
  const ix = (counts) => M.index(counts);
  // Worked values quoted in the text (each checked by hand in the author report)
  const dA = D("evenA"), dB = D("unevenB"), dM = D("margin"), dC = D("crop"), dMg = D("mangrove"), dSf = D("sandflat");
  const shore = [15, 10, 8, 4, 3], dShore = ix(shore);
  const pondX = [12, 8, 5, 3, 1, 1], pondY = [30, 3, 2, 1], dPX = ix(pondX), dPY = ix(pondY);
  const tiny = ix([4, 3, 2]);
  const rareBefore = ix([10, 10, 1]), rareAfter = ix([10, 10, 5]);
  const expect = (cond, msg) => { if (!cond) console.warn("3.1.11.2 data check failed:", msg); };
  expect(M.fix(dA.d) === "5.21" && M.fix(dB.d) === "1.18" && M.fix(dM.d) === "6.39" && M.fix(dC.d) === "1.72" && M.fix(dMg.d) === "3.49" && M.fix(dSf.d) === "1.49" && M.fix(dShore.d) === "4.17" && M.fix(tiny.d, 1) === "3.6", "index values");
  // Field margin area (illustrative geometry): a 6 m margin round a square 10 ha field
  const side = Math.sqrt(100000), marginHa = (4 * side * 6 - 4 * 36) / 10000, marginPct = (100 * marginHa) / 10;
  // Hedgerow scenario (illustrative pitfall-trap counts, deliberately different from the field-margin data)
  const hedgeBase = [11, 9, 7, 6, 4, 3, 2, 2, 1], hedgeField = [24, 6, 3, 2], dHB = ix(hedgeBase), dHF = ix(hedgeField);
  expect(M.fix(dHB.d) === "7.17" && M.fix(dHF.d) === "2.02", "hedgerow scenario values");


  // ---- Biodiversity Investigator (kind bdvInvestigator): communities come from the model; answers computed here ----
  const inv = { kind: "bdvInvestigator", title: "Biodiversity Investigator", note: "Choose a community (illustrative counts). Change the abundances to see what happens to species richness and d, and work through the index of diversity step by step: N, each n(n − 1), Σn(n − 1), N(N − 1) and d. The last three communities show when the formula cannot be used.",
    communities: ["evenA", "unevenB", "margin", "crop", "mangrove", "sandflat", "singletons", "one", "empty"],
    items: [{ label: "Questions on the investigator", questions: [
      { id: `q-${R}-iv1`, ref: R, stmts: S(1, 3), type: "gap", marks: 3, stem: "Open Site A and Site B. Give the values of d to 2 decimal places.", text: "Species richness of each site: {{1}}. Index of diversity of Site A: {{2}}. Index of diversity of Site B: {{3}}.", answers: { 1: ["5", "five"], 2: [M.fix(dA.d)], 3: [M.fix(dB.d)] }, explanation: `Both sites have 5 species and N = 100, so N(N − 1) = 9900. Site A: Σn(n − 1) = 5 × 20 × 19 = 1900, d = 9900 ÷ 1900 = ${M.fix(dA.d)}. Site B: Σ = 92 × 91 + 4 × (2 × 1) = 8380, d = 9900 ÷ 8380 = ${M.fix(dB.d)}.` },
      { id: `q-${R}-iv2`, ref: R, stmts: S(1, 2), type: "mcq", marks: 1, stem: "Sites A and B have the same species richness but very different values of d. Why?", options: ["d depends on how evenly the individuals are spread among the species, not just on the number of species", "Site B was sampled with fewer quadrats, so fewer of its species were found and recorded", "d measures only the total number of individuals, which is different at the two sites", "Site A contains more species, because its individuals are spread more evenly"], answer: 0, explanation: "The index relates the number of species to the number of individuals of each; Site B is dominated by one species." },
      { id: `q-${R}-iv3`, ref: R, stmts: S(3), type: "gap", marks: 3, stem: "Open the field margin community and work through the steps.", text: "N = {{1}}. Σn(n − 1) = {{2}}. d to 2 decimal places = {{3}}.", answers: { 1: [String(dM.N)], 2: [String(dM.sigma)], 3: [M.fix(dM.d)] }, explanation: `N = ${dM.N}; Σn(n − 1) = ${dM.terms.join(" + ")} = ${dM.sigma}; N(N − 1) = ${dM.N} × ${dM.N - 1} = ${dM.top}; d = ${dM.top} ÷ ${dM.sigma} = ${M.fix(dM.d)}.` },
      { id: `q-${R}-iv4`, ref: R, stmts: S(3, 4), type: "gap", marks: 2, stem: "Compare the mangrove edge with the bare sand flat beside it. Give each value to 2 decimal places.", text: "d for the mangrove edge: {{1}}. d for the sand flat: {{2}}.", answers: { 1: [M.fix(dMg.d)], 2: [M.fix(dSf.d)] }, explanation: `Mangrove: ${dMg.top} ÷ ${dMg.sigma} = ${M.fix(dMg.d)}. Sand flat: ${dSf.top} ÷ ${dSf.sigma} = ${M.fix(dSf.d)}. The mangrove edge supports more species, more evenly.` },
      { id: `q-${R}-iv5`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Open 'every species seen once'. Why does the investigator not give a value of d?", options: ["Every n(n − 1) is 0, so Σn(n − 1) = 0 and the formula would divide by zero", "There are too many species", "N is zero", "d is always 0 for small samples"], answer: 0, explanation: "With n = 1 for every species, each n(n − 1) = 1 × 0 = 0. Dividing by zero has no value, so d cannot be calculated with this formula; a larger sample is needed." },
      { id: `q-${R}-iv6`, ref: R, stmts: S(2, 3), type: "mcq", marks: 1, stem: `Use 'change abundances'. A community has three species with 10, 10 and 1 individuals (d = ${M.fix(rareBefore.d)}). The rare species increases to 5 individuals. What happens to d?`, options: [`It rises, to ${M.fix(rareAfter.d)}, because the abundances become more even`, "It falls, because N increases", "It stays the same, because richness is unchanged", "It cannot be calculated"], answer: 0, explanation: `N = 25, N(N − 1) = 600, Σ = 90 + 90 + 20 = 200, d = ${M.fix(rareAfter.d)}. Richness is unchanged but evenness increases.` },
    ] }] };

  // ---- Decision scenarios (formerly the Conservation Decision Challenge): ordinary page questions, same ids. Each stem
  // carries its own evidence; the self-marked answers have no single correct recommendation. ----
  const reasonScheme = (extra) => [{ point: "States a recommendation (any option can earn full marks)", marks: 1 }, { point: "Uses at least one piece of the evidence given, accurately (quotes a value)", marks: 1 }, { point: "Identifies a benefit and a cost (a trade-off) of the chosen option, for food production and for biodiversity", marks: 1 }, { point: extra, marks: 1 }];
  const hedgeCtx = `<div class="notice small"><strong>Scenario: hedgerows on a cereal farm</strong> (hypothetical farm; illustrative data). A farmer has 4 km of old hedgerow between small wheat fields. Larger fields are quicker to work with big machinery; hedgerows take some land out of production and need cutting.${ev([["Cropped area that the 2 m uncropped strip on each side of the hedgerows would add if the hedgerows were removed", "about 1.6 ha (4000 m × 4 m), plus the ground under the hedges"], ["Index of diversity of ground invertebrates, pitfall traps at the base of a hedgerow", `${M.fix(dHB.d)} (${dHB.richness} species)`], ["Index of diversity in the field centre, same number of traps", `${M.fix(dHF.d)} (${dHF.richness} species)`], ["Payment offered for keeping and managing hedgerows", "covers about half the cutting cost"]])}</div>`;
  const sprayCtx = `<div class="notice small"><strong>Scenario: spraying for aphids</strong> (hypothetical trial; illustrative data). Aphids feed on crop sap and can reduce yield. A broad-spectrum insecticide kills aphids but also many other insects, including ladybirds and other predators that eat aphids. A trial compared three treatments in plots of the same field.${ev([["No spray", "38 aphids per plant at peak · 6.0 ladybirds per m² · yield 7.1 t per ha"], ["Spray the whole crop twice", "4 aphids per plant · 0.5 ladybirds per m² · yield 7.9 t per ha"], ["Spray only when aphids exceed a threshold (once)", "12 aphids per plant · 3.5 ladybirds per m² · yield 7.7 t per ha"]])}</div>`;
  const scenarioQs = [
    { id: `q-${R}-cd1`, ref: R, stmts: S(4, 5), type: "mcq", marks: 1, stem: `${hedgeCtx}What do the pitfall-trap data support?`, options: ["Ground invertebrate diversity was higher at the base of the hedgerow than in the field centre at the time sampled", "Removing the hedgerows will reduce wheat yield", "The hedgerow causes the higher diversity in every season", "The field centre has no invertebrates"], answer: 0, explanation: "The data compare two places at one time. They are consistent with hedgerows supporting more species, but do not on their own show cause, seasonal patterns or yield effects." },
    { id: `q-${R}-cd2`, ref: R, stmts: S(5, 4), type: "short", marks: 4, stem: `${hedgeCtx}The farmer could remove all the hedgerows; keep them and join the payment scheme; or remove one hedgerow to merge two fields, keep the rest and plant a new hedgerow elsewhere. Recommend what the farmer should do and justify your recommendation using the evidence, including at least one trade-off. (4 marks; there is no single correct answer)`, scheme: reasonScheme("Identifies a limitation of the evidence or further information needed (e.g. one sampling date; yield data; cost over several years; which species are present)"), model: `Example (one of several valid answers): keep the hedgerows and join the scheme. Invertebrate diversity at the base of the hedgerow (d = ${M.fix(dHB.d)}, ${dHB.richness} species) is much higher than in the field centre (d = ${M.fix(dHF.d)}, ${dHF.richness} species), so the hedgerows appear to provide habitat and food that the crop does not; once removed, old hedgerows take decades to replace. The cost is at least 1.6 ha that could be cropped, and cutting costs that the payment covers only in part. The data come from one sampling period and say nothing about yield, so the farmer would want several years of yield and cost figures before deciding.`, commonErrors: "Choosing an option without using the data; ignoring the farmer's costs; treating one sample as proof." },
    { id: `q-${R}-cd5`, ref: R, stmts: S(4, 5), type: "mcq", marks: 1, stem: `${sprayCtx}Compared with spraying the whole crop twice, what does threshold spraying achieve in this trial?`, options: ["About 75 % of the yield gain of routine spraying, with seven times as many ladybirds", "A higher yield than routine spraying, because more aphid predators survive in the crop", "The same number of aphids per plant as no spray, but a higher yield than no spray", "About half the yield gain of routine spraying, with the same number of ladybirds as no spray"], answer: 0, explanation: "Yield gain over no spray: routine 7.9 − 7.1 = 0.8 t ha⁻¹; threshold 7.7 − 7.1 = 0.6 t ha⁻¹, which is 75 % of 0.8. Ladybirds: 3.5 ÷ 0.5 = 7 times as many." },
    { id: `q-${R}-cd6`, ref: R, stmts: S(5, 4), type: "short", marks: 4, stem: `${sprayCtx}Which treatment would you recommend? Justify your choice using the data and the trade-offs. (4 marks; there is no single correct answer)`, scheme: reasonScheme("Notes a limitation: one field and one season; no replicates or variation shown; ladybirds are only one group of non-target insects"), model: "Example (one of several valid answers): spray the whole crop routinely. In this trial it gave the highest yield, 7.9 t ha⁻¹ against 7.7 t ha⁻¹ for threshold spraying and 7.1 t ha⁻¹ with no spray, and the fewest aphids (4 per plant), so it produces the most food from the same area of land. The cost is to non-target insects: ladybirds fell to 0.5 per m² from 6.0 with no spray, so fewer aphid predators (and probably other insects, such as pollinators) survive; spraying twice also costs more and raises the risk of resistance. The trial is one field in one season with no replicates shown, so the 0.2 t ha⁻¹ advantage over threshold spraying may not be reliable; repeat trials, and the value of the extra yield compared with the cost of the extra spray, would be needed before deciding.", commonErrors: "Choosing routine spraying because yield is highest, without weighing non-target effects; or 'no spray' without considering food production." },
  ];

  window.BIO.content[R] = {
    status: "draft",
    banner: "mangroves-uae", bannerText: "A mangrove edge, a hedgerow, a field margin: counting the species, and how many of each, tells you how diverse a community is. Human activities change those counts, and food production has to be balanced against conservation.",
    keywords: ["species diversity", "species richness", "community", "population", "abundance", "evenness", "index of diversity", "N(N − 1)", "Σn(n − 1)", "biodiversity", "habitat", "hedgerow", "field margin", "monoculture", "pesticide", "herbicide", "fertiliser", "set-aside", "agri-environment scheme", "conservation", "food production", "mangrove", "Avicennia marina", "quadrat", "pitfall trap"],
    notes: () => `
<div class="notice"><strong>What the specification requires (3.1.11.2).</strong> <strong>Species richness</strong> is a measure of the number of different species in a community. Biodiversity can also be measured by calculating an <strong>index of diversity</strong>, which describes the relationship between the number of different species in a community and the number of individuals in each species. One example is <strong>d = N(N − 1) ÷ Σn(n − 1)</strong>, where N = total number of organisms of all species and n = total number of organisms of each species: you must <strong>recall this formula and use it</strong> to calculate values from given data. <strong>Many human activities reduce biodiversity</strong>, and you should understand <strong>the balance between human food production and conservation</strong>. <span class="badge teal">required</span> <span class="badge">supporting</span> <span class="badge amber">stretch</span></div>

<h2 data-stmt="${R}.s1">1. Populations, communities and species richness <span class="badge teal">required</span></h2>
<ul><li><span class="badge">supporting</span> A <strong>population</strong> is all the organisms of one species living in the same area at the same time.</li>
<li><span class="badge">supporting</span> A <strong>community</strong> is all the populations of different species living in the same area at the same time.</li>
<li><strong>Species richness</strong> is the number of different species in a community. It is found by identifying and listing the species present; it does not take into account how many individuals of each species there are.</li>
<li><span class="badge">supporting</span> The number of individuals of a species is its <strong>abundance</strong>. <strong>Biodiversity</strong> is the variety of life; it can be considered at the level of genes (3.1.11.1), species (this section) and habitats.</li></ul>

<h2 data-stmt="${R}.s1 ${R}.s2">2. Richness is not the whole story <span class="badge teal">required</span></h2>
<p>Two communities can have the same number of species and still differ greatly. Below, Sites A and B each have <strong>five species and 100 organisms</strong>, so their species richness is the same. (Four of the species are shared; Site B has perennial ryegrass where Site A has yarrow, so the two are drawn with different symbols.) In Site A every species has 20 individuals; in Site B one species has 92 and the other four only 2 each. Site A is clearly more diverse: if you picked organisms at random you would be far more likely to find different species. An index of diversity captures this, because it takes account of the <strong>number of individuals of each species</strong> as well as the number of species.</p>
<div class="figure"><div class="fig-view">${A.evennessFig()}</div></div>
<p><span class="badge">supporting</span> How equally the individuals are spread among the species is called <strong>evenness</strong>. The index of diversity increases with species richness and with evenness.</p>

<h2 data-stmt="${R}.s2 ${R}.s3">3. The index of diversity <span class="badge teal">required</span></h2>
<div class="notice amber" style="text-align:center;font-size:1.05rem"><strong>d = N(N − 1) ÷ Σn(n − 1)</strong><br><span class="small">N = total number of organisms of all species · n = total number of organisms of each species · Σ = "the sum of"</span></div>
<p><strong>Method.</strong> (1) Add up all the organisms to find <strong>N</strong>. (2) For each species, calculate <strong>n(n − 1)</strong>. (3) Add these to find <strong>Σn(n − 1)</strong>. (4) Calculate <strong>N(N − 1)</strong>. (5) Divide: <strong>d = N(N − 1) ÷ Σn(n − 1)</strong>, and round as the question asks. A table keeps the working clear: in the <strong>Biodiversity Investigator</strong>, choose "Field margin" and then "Show all steps" to see the method laid out for eight species.</p>
<div class="notice"><strong>Worked example (Sites A and B).</strong> Both have N = 100, so N(N − 1) = 100 × 99 = 9900.<br>Site A: Σn(n − 1) = 5 × (20 × 19) = 1900; d = 9900 ÷ 1900 = <strong>${M.fix(dA.d)}</strong>.<br>Site B: Σn(n − 1) = (92 × 91) + 4 × (2 × 1) = 8372 + 8 = 8380; d = 9900 ÷ 8380 = <strong>${M.fix(dB.d)}</strong>.</div>
<p><strong>Common slips.</strong> Using n² instead of n(n − 1); forgetting that a species with one individual contributes 1 × 0 = 0 (it still counts in N); dividing the other way up; rounding too early (keep the whole numbers until the final division).</p>

<h2 data-stmt="${R}.s2 ${R}.s3">4. Interpreting values of d <span class="badge teal">required</span></h2>
<ul><li>A <strong>higher</strong> value of d means a <strong>more diverse</strong> community: more species, or individuals more evenly spread among the species, or both.</li>
<li>If only <strong>one species</strong> is present, N = n, so d = N(N − 1) ÷ N(N − 1) = <strong>1</strong>, the lowest possible value. <span class="badge">supporting</span> Whenever d can be calculated, d ≥ 1, because Σn(n − 1) can never be larger than N(N − 1).</li>
<li><span class="badge">supporting</span> d has <strong>no units</strong>. Compare values only between samples collected in the same way (same method, sampling effort, area and season).</li>
<li><span class="badge">supporting</span> d does not say <strong>which</strong> species are present. A site with a lower d might hold a rare or endangered species, so conservation decisions use more than one measure.</li></ul>

<h2 data-stmt="${R}.s3">5. When d cannot be calculated <span class="badge teal">required</span></h2>
<p>The formula involves a division, so it fails whenever the bottom line, Σn(n − 1), is zero:</p>
<ul><li><strong>No organisms</strong> (N = 0): there is nothing to describe.</li>
<li><strong>One organism</strong> (N = 1): N(N − 1) = 0 and Σn(n − 1) = 0, giving 0 ÷ 0, which has no value.</li>
<li><strong>Every species represented by one individual</strong>: each n(n − 1) = 1 × 0 = 0, so Σn(n − 1) = 0 and the formula would divide by zero.</li></ul>
<p>In these cases say that <strong>d cannot be calculated with this formula</strong>; do not write 0 or infinity. A larger sample is needed.</p>

<h2 data-stmt="${R}.s1 ${R}.s3">6. Getting the data <span class="badge">supporting</span></h2>
<p>Counts come from <strong>samples</strong>, because a whole community can rarely be counted (3.1.6). Plants and slow-moving animals are counted in quadrats placed at random coordinates; ground invertebrates can be caught in pitfall traps. Samples must be large enough to be representative, collected the same way at each site, and organisms must be identified to species (or reliably separated as different kinds, for example "ground beetle sp. 1" and "sp. 2"). Counting a group such as "spiders" as one species underestimates richness and changes d.</p>
${P("quadrat-sampling")}

<h2 data-stmt="${R}.s4">7. Many human activities reduce biodiversity <span class="badge teal">required</span></h2>
<div class="figure"><div class="fig-view">${A.threatsFig()}</div></div>
<table class="tbl"><thead><tr><th>Activity</th><th>How it reduces biodiversity</th></tr></thead><tbody>
<tr><td>Clearing land for farming, building, roads and coastal development; draining wetlands</td><td>Removes habitats and the food, shelter and breeding sites of many species; leaves small, isolated fragments that support fewer species.</td></tr>
<tr><td>Removing hedgerows; ploughing field margins</td><td>Removes habitats, food plants and nesting sites, and corridors that link habitats.</td></tr>
<tr><td>Monoculture (one crop over a large area)</td><td>One plant species replaces many; fewer niches and food sources for animals.</td></tr>
<tr><td>Herbicides and insecticides</td><td>Herbicides kill weeds that are food plants for insects; broad-spectrum insecticides kill non-target insects, including pollinators and predators, and so their predators lose food.</td></tr>
<tr><td>Fertilisers</td><td>Run-off into rivers and lakes can cause eutrophication, lowering oxygen and killing aquatic organisms; on grassland, high fertility lets a few fast-growing species out-compete others (lower evenness, as in Site B).</td></tr>
<tr><td>Pollution; overfishing and overharvesting; introduced species; climate change</td><td>Kill organisms directly, reduce populations faster than they can recover, out-compete or prey on native species, or change conditions faster than species can adapt or move.</td></tr></tbody></table>
<p>The effect can be on <strong>richness</strong> (species lost), on <strong>evenness</strong> (a few species dominate), or both; either lowers the index of diversity.</p>

<h2 data-stmt="${R}.s5 ${R}.s4">8. The balance between food production and conservation <span class="badge teal">required</span></h2>
<p>The human population needs food, and farmers need an income. <strong>Intensive</strong> farming increases yield per hectare (large fields, monoculture, fertilisers, pesticides, machinery) but tends to reduce biodiversity on the farm. Conservation measures can retain or restore biodiversity but often cost money or reduce the area cropped. The aim is a <strong>balance</strong>: enough food produced, with as much biodiversity retained as possible. There is rarely a single right answer; decisions weigh evidence and trade-offs.</p>
<div class="figure"><div class="fig-view">${A.farmFig()}</div></div>
<table class="tbl"><thead><tr><th>Measure</th><th>Benefit for biodiversity</th><th>Cost or trade-off for food production</th></tr></thead><tbody>
<tr><td>Keeping, managing and replanting <strong>hedgerows</strong></td><td>Habitat, food (flowers, berries), nesting sites, shelter; corridors between habitats</td><td>Land not cropped; cutting costs; smaller fields slow machinery</td></tr>
<tr><td>Uncropped <strong>field margins</strong></td><td>Habitat and food for invertebrates (including pollinators and predators of crop pests), birds and mammals; can reduce run-off into water</td><td>Cropped area lost (about ${M.fix(marginPct, 1)} % for a 6 m margin round a square 10 ha field); effects on the yield of the rest of the field vary</td></tr>
<tr><td><strong>Set-aside</strong>: leaving some land uncropped</td><td>Habitat for many species to recover</td><td>Less food from that land</td></tr>
<tr><td><strong>Crop rotation</strong> and mixed farming instead of continuous monoculture</td><td>More variety of habitats over the farm and through the years</td><td>More complex management; some crops earn less</td></tr>
<tr><td>Reducing pesticide use: spraying only when pests exceed a threshold; biological control (natural predators)</td><td>Fewer non-target organisms killed</td><td>Monitoring needed; some yield may be lost</td></tr>
<tr><td><strong>Agri-environment schemes</strong>: payments to farmers who manage land to benefit wildlife</td><td>Encourage the measures above</td><td>Cost to the public; benefits depend on how well schemes are designed and followed</td></tr></tbody></table>
<p><span class="badge">supporting</span> Two broad strategies are debated: <strong>land sharing</strong> (wildlife-friendly farming spread across all farmland) and <strong>land sparing</strong> (farming intensively on some land so that other land can be left as natural habitat). Which works better depends on the species and the place.</p>
<p><strong>Evaluating evidence.</strong> When asked to evaluate a measure, use the data given, identify a benefit and a cost, and say what further evidence would be needed (for example yields over several years, replicated sites, which species benefit). Avoid treating one sample as proof. Two decision scenarios (hedgerows, and spraying for aphids) are in Check yourself.</p>
${P("hedgerow-farmland")}

<h2 data-stmt="${R}.s4 ${R}.s5">9. A local example: grey mangroves <span class="badge">supporting</span></h2>
<p>On the coast of Abu Dhabi the grey mangrove, <em>Avicennia marina</em>, grows between the tides. Mangroves provide food and shelter for many species of fish, invertebrates and birds, and act as a nursery for juvenile fish, so a mangrove edge usually supports a more diverse community than bare sand nearby. Coastal development and land clearance are among the human activities that threaten them. Conserving mangroves protects this biodiversity and also supports fish stocks, so here conservation and food production from fisheries can go together.</p>`,
    diagrams: [
      { id: "d-3.1.11.2-1", title: "Same species richness, different diversity", status: "reviewed", caption: `Sites A and B each have five species and 100 organisms. In A the individuals are spread evenly (20 of each, d = ${M.fix(dA.d)}); in B one species, perennial ryegrass (not present in A), dominates (92, 2, 2, 2, 2; d = ${M.fix(dB.d)}). Four species are shared; yarrow is found only in A and ryegrass only in B. Illustrative counts; each shape and colour is one species, as the legend shows.`, alt: "Two square quadrats of small symbols with a legend below. The left quadrat has five kinds of symbol in equal numbers: buttercup, plantain, clover, daisy and yarrow. The right is almost filled with a sixth kind, perennial ryegrass, with two each of buttercup, plantain, clover and daisy. Captions give richness 5, N 100, and d 5.21 and 1.18.", svg: A.evennessFig() },
      { id: "d-3.1.11.2-3", title: "How human activities reduce biodiversity", status: "reviewed", caption: "Activities remove or damage habitats, food and breeding sites, or kill organisms directly; species are lost (lower richness) or a few come to dominate (lower evenness), and the index of diversity falls.", alt: "Six boxes of human activities on the left, each with an arrow to a central box about fewer habitats, niches, food and shelter. Two arrows lead from it to 'some species lost: lower species richness' and 'a few species dominate: less even abundances', and both lead to 'lower index of diversity'.", svg: A.threatsFig() },
      { id: "d-3.1.11.2-4", title: "Farmland with and without conservation measures", status: "reviewed", caption: "Left: large fields of one crop with hedgerows removed. Right: smaller fields in rotation, with hedgerows, an uncropped margin, a pond and trees. The right-hand farm offers more habitats but crops less land. Schematic.", alt: "Two farm plans. Left: one large wheat field. Right: four fields of wheat, beans, barley and grass separated by hedgerows, one with a pale green margin, plus a pond and a group of trees.", svg: A.farmFig() },
    ],
    interactives: [inv],
    focus: [
      { slot: "mangroves-uae", title: "Grey mangroves on the Abu Dhabi coast", ref: R, explanation: () => `<p>Along the shores and backwaters of Abu Dhabi, the grey mangrove <em>Avicennia marina</em> is the only dominant mangrove species. It tolerates conditions few trees could: twice-daily flooding by seawater, waterlogged mud with little oxygen, and high temperatures. <span class="badge">supporting</span> Pencil-like aerial roots (pneumatophores) grow up from the mud and let air reach the roots, and the leaves excrete excess salt through salt glands. The stands provide food and shelter for many marine and bird species and act as a nursery for juvenile fish, so a mangrove edge usually supports a more diverse community than bare sand nearby. Coastal development and land clearance are among the threats to them. (Facts from the Environment Agency – Abu Dhabi.)</p>`,
        question: { id: `q-${R}-fx1`, ref: R, stmts: S(4, 5), type: "short", marks: 3, stem: "Explain why clearing mangroves for a coastal development could reduce both biodiversity and the amount of food available from fisheries. (3 marks)", scheme: [{ point: "Removes the habitat / food and shelter for many marine and bird species, so species are lost or decline (lower richness / index of diversity)", marks: 1 }, { point: "Mangroves are a nursery: high densities of juvenile fish shelter there", marks: 1 }, { point: "So fewer young fish survive to join adult stocks, reducing the fish available to fisheries", marks: 1 }], model: "Mangroves provide food and shelter for many species of fish, invertebrates and birds, so clearing them removes these habitats and species decline or disappear locally, lowering biodiversity. They also act as a nursery where high densities of juvenile fish shelter; fewer juveniles would survive to adulthood, so fish stocks that fisheries depend on could fall.", commonErrors: "Discussing only carbon storage; not linking the nursery role to food." } },
      { slot: "hedgerow-farmland", title: "Hedgerows and field margins", ref: R, explanation: () => `<p>Hedgerows are lines of shrubs and small trees that separate fields. Over the twentieth century many were removed in intensively farmed countries to make larger fields suited to bigger machinery. A hedgerow provides habitat, food (flowers, fruits, seeds, and the insects that feed on them), nesting sites for birds and shelter, and connects other habitats such as woodland, so animals can move between them. Uncropped margins beside hedgerows add grassy and flowering plants. Many countries now run agri-environment schemes that pay farmers to keep, manage or replant hedgerows and to leave margins. These measures cost the farmer cropped land and time, and their benefit for yield, for example through more predators of crop pests or more pollinators, varies between farms and crops, which is why evidence from several sites and years is needed.</p>`,
        question: { id: `q-${R}-fx2`, ref: R, stmts: S(4, 5), type: "short", marks: 3, stem: "Explain how removing hedgerows reduces biodiversity on farmland, and give one reason why a farmer might still choose to remove them. (3 marks)", scheme: [{ point: "Loss of habitat / nesting sites / shelter", marks: 1 }, { point: "Loss of food sources (flowers, fruits, seeds, insects) and of corridors linking habitats, so fewer species can live on the farm", marks: 1 }, { point: "Reason: larger fields / more land cropped / easier use of large machinery / lower maintenance cost, so more food or income", marks: 1 }], model: "Hedgerows provide habitats, nesting sites and shelter, and food such as flowers, fruits, seeds and insects; they also link habitats so animals can move between them. Removing them takes away these resources, so fewer species, and fewer individuals of some species, can live on the farm. A farmer might still remove them to make larger fields that are quicker to work with big machinery and that add cropped area, increasing food production and income.", commonErrors: "Vague answers such as 'animals lose their home' with no specific resource." } },
      { slot: "quadrat-sampling", title: "Counting for an index of diversity", ref: R, explanation: () => `<p>A quadrat frame placed at random coordinates gives a random sample of a habitat (3.1.6). To calculate an index of diversity every organism inside the frame must be identified to species and counted. For plants that spread by runners or grow in clumps it is often hard to say where one individual ends, so ecologists may record percentage cover instead; the index of diversity in this specification needs counts of individuals, so it suits organisms that can be counted, such as many animals and separate plants. The same number and size of quadrats should be used at each site being compared, and enough quadrats taken that adding more no longer changes the list of species much.</p>`,
        question: { id: `q-${R}-fx3`, ref: R, stmts: S(3, 1), type: "short", marks: 3, stem: "A student uses quadrats to compare the index of diversity of plants in a mown lawn and in an unmown meadow. Give three ways the student should make the comparison valid. (3 marks)", scheme: [{ point: "Same number and size of quadrats at each site", marks: 1 }, { point: "Quadrats placed at random (random coordinates) at both sites", marks: 1 }, { point: "Same time / season; identify every organism to species and count individuals the same way (or enough quadrats to be representative)", marks: 1 }], model: "Use the same number of quadrats of the same size at both sites; place them at random coordinates so that neither site is sampled with bias; sample at the same time of year and count individuals of every species in the same way, taking enough quadrats that the species list is representative.", commonErrors: "'Do it fairly' with no specific control." } },
    ],
    examFocus: `<ul><li>Species richness = the <strong>number of different species</strong> in a community. It ignores how many individuals each has.</li><li>Index of diversity: you must <strong>recall</strong> d = N(N − 1) ÷ Σn(n − 1), with N = total organisms of all species, n = total of each species.</li><li>Show the working in a table: n, n − 1, n(n − 1), Σ; then N(N − 1); then divide. A species with one individual contributes 0 to Σ but counts in N.</li><li>Higher d = more diverse. d = 1 when only one species is present. Same richness can give different d (evenness).</li><li>If Σn(n − 1) = 0 (no organisms, one organism, or every species seen once), d cannot be calculated: say so.</li><li>Human activities: name the activity <em>and</em> the mechanism (habitat, food, nesting sites, corridors, non-target species killed, eutrophication, competition).</li><li>Food production v conservation: give both sides; name specific measures (hedgerows, field margins, set-aside, crop rotation, reduced or targeted pesticide use, agri-environment schemes) and a cost of each; use data and say what further evidence is needed.</li></ul>`,
    synoptic: [
      { ref: "3.1.11.1", text: "Genetic diversity within species complements species diversity within communities." },
      { ref: "3.1.6", text: "Random sampling with quadrats; sample size and representative data." },
      { ref: "3.1.10.1", text: "Counting species depends on identifying them correctly; the species concept." },
      { ref: "3.1.3.2", text: "Pesticides and herbicides often act by inhibiting enzymes in target organisms." },
    ],
    quickCheck: [
      { id: `q-${R}-qc1`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Species richness is:", options: ["the number of different species in a community", "the number of individuals in a community", "the number of individuals of the commonest species", "the index of diversity multiplied by N"], answer: 0, explanation: "Richness counts species, not individuals." },
      { id: `q-${R}-qc2`, ref: R, stmts: S(3), type: "gap", marks: 1, stem: `A sample contains three species with 4, 3 and 2 individuals. Give d to 1 decimal place.`, text: "d = {{1}}", answers: { 1: [M.fix(tiny.d, 1)] }, explanation: `N = 9, N(N − 1) = 72; Σn(n − 1) = 12 + 6 + 2 = 20; d = 72 ÷ 20 = ${M.fix(tiny.d, 1)}.` },
      { id: `q-${R}-qc3`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Two ponds have the same species richness. Pond X has a higher index of diversity than pond Y. This means:", options: ["individuals are spread more evenly among the species in pond X", "pond X has more species", "pond Y has more individuals", "pond X has fewer individuals of every species"], answer: 0, explanation: "With equal richness, the difference comes from the numbers of individuals of each species." },
      { id: `q-${R}-qc4`, ref: R, stmts: S(4, 5), type: "mcq", marks: 1, stem: "Which farming practice is most likely to INCREASE biodiversity on farmland?", options: ["Leaving uncropped margins round fields", "Removing hedgerows to enlarge fields", "Spraying broad-spectrum insecticide routinely", "Growing one crop over the whole farm every year"], answer: 0, explanation: "Field margins provide habitats and food; the others reduce biodiversity." },
    ],
    flashcards: [
      { id: `f-${R}-1`, front: "Define species richness.", back: "The number of different species in a community." },
      { id: `f-${R}-2`, front: "Define community (supporting) and population (supporting).", back: "Community: all the populations of different species in the same area at the same time. Population: all the organisms of one species in an area at one time." },
      { id: `f-${R}-3`, front: "What does an index of diversity describe?", back: "The relationship between the number of different species in a community and the number of individuals in each species." },
      { id: `f-${R}-4`, front: "Write the index of diversity (must be recalled).", back: "d = N(N − 1) ÷ Σn(n − 1)" },
      { id: `f-${R}-5`, front: "In d = N(N − 1) ÷ Σn(n − 1), what are N and n?", back: "N = total number of organisms of all species. n = total number of organisms of each species." },
      { id: `f-${R}-6`, front: "Steps to calculate d.", back: "Find N; work out n(n − 1) for each species; add them (Σ); work out N(N − 1); divide N(N − 1) by Σn(n − 1); round at the end." },
      { id: `f-${R}-7`, front: "What does a species with one individual contribute?", back: "1 × 0 = 0 to Σn(n − 1), but it still counts 1 towards N (and towards richness)." },
      { id: `f-${R}-8`, front: "d for a community of one species?", back: "1 (N = n, so the top and bottom are equal). Whenever d is defined, d ≥ 1." },
      { id: `f-${R}-9`, front: "Why can two sites with the same richness have different d?", back: "d also depends on how evenly the individuals are spread among the species; one dominant species lowers d." },
      { id: `f-${R}-10`, front: "When can d not be calculated?", back: "When Σn(n − 1) = 0: no organisms, one organism, or every species represented by one individual. Say it cannot be calculated; never write 0 or infinity." },
      { id: `f-${R}-11`, front: `Sites A (20, 20, 20, 20, 20) and B (92, 2, 2, 2, 2): values of d.`, back: `A: 9900 ÷ 1900 = ${M.fix(dA.d)}. B: 9900 ÷ 8380 = ${M.fix(dB.d)}. Same richness, different evenness.` },
      { id: `f-${R}-12`, front: "Name five human activities that reduce biodiversity.", back: "Clearing land (farming, building, coastal development); hedgerow removal and monoculture; pesticides and herbicides; fertiliser run-off and other pollution; overfishing; introduced species; climate change." },
      { id: `f-${R}-13`, front: "How does hedgerow removal reduce biodiversity?", back: "Removes habitats, food (flowers, berries, insects), nesting sites, shelter and corridors linking habitats." },
      { id: `f-${R}-14`, front: "How do pesticides reduce biodiversity?", back: "Insecticides kill non-target insects (pollinators, pest predators), removing food for their predators; herbicides kill weeds that are food plants for insects." },
      { id: `f-${R}-15`, front: "Conservation measures on farmland.", back: "Keep and replant hedgerows; uncropped field margins; set-aside; crop rotation; targeted or reduced pesticide use; agri-environment schemes that pay farmers." },
      { id: `f-${R}-16`, front: "What is the trade-off in conserving biodiversity on farms?", back: "Measures often reduce cropped area or yield, or cost money and time; the aim is enough food with as much biodiversity retained as possible." },
    ],
    questions: [
      // ---- MCQ ----
      { id: `q-${R}-m1`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Which term describes all the populations of different species living in the same area at the same time?", options: ["Community", "Population", "Species richness", "Habitat"], answer: 0, explanation: "A community is made of populations of different species." },
      { id: `q-${R}-m2`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "A rocky-shore survey records 14 species and 362 individuals. The species richness is:", options: ["14", "362", "376", "25.9"], answer: 0, explanation: "Richness is the number of species." },
      { id: `q-${R}-m3`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "An index of diversity describes the relationship between:", options: ["the number of different species and the number of individuals in each species", "the number of individuals and the area sampled", "the number of species and the area of the habitat", "the genetic diversity and the number of populations"], answer: 0, explanation: "This is the specification's description." },
      { id: `q-${R}-m4`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "In the index of diversity d = N(N − 1) ÷ Σn(n − 1), N is:", options: ["the total number of organisms of all species", "the number of species", "the number of organisms of the commonest species", "the number of samples taken"], answer: 0, explanation: "n is the number of each species; N is the total of all species." },
      { id: `q-${R}-m5`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: `Three species have 4, 3 and 2 individuals. What is the index of diversity?`, options: [M.fix(tiny.d, 1), "0.28", "4.5", "2.0"], answer: 0, explanation: `N = 9: 72 ÷ (12 + 6 + 2) = ${M.fix(tiny.d, 1)}. 0.28 is the fraction upside down.` },
      { id: `q-${R}-m6`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "A field contains only one species of plant, with 250 individuals. What is d?", options: ["1", "0", "250", "It cannot be calculated"], answer: 0, explanation: "N(N − 1) and Σn(n − 1) are both 250 × 249, so d = 1." },
      { id: `q-${R}-m7`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "A small sample contains six species, each represented by one individual. What can be said about d?", options: ["It cannot be calculated, because Σn(n − 1) = 0", "d = 0", "d = 6", "d = 30"], answer: 0, explanation: "Each n(n − 1) = 0, so the formula would divide by zero." },
      { id: `q-${R}-m8`, ref: R, stmts: S(2, 3), type: "mcq", marks: 1, stem: `Two communities each have 4 species and 40 individuals. Community 1: 10, 10, 10, 10. Community 2: 31, 3, 3, 3. Which statement is correct?`, options: [`Community 1 has the higher index (${d2([10, 10, 10, 10])} v ${d2([31, 3, 3, 3])})`, "They have the same index because richness and N are equal", `Community 2 has the higher index (${d2([31, 3, 3, 3])} v ${d2([10, 10, 10, 10])})`, "Neither index can be calculated"], answer: 0, explanation: `N(N − 1) = 1560 for both. Community 1: Σ = 4 × 90 = 360, d = ${d2([10, 10, 10, 10])}. Community 2: Σ = 930 + 3 × 6 = 948, d = ${d2([31, 3, 3, 3])}.` },
      { id: `q-${R}-m9`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Why does an index of diversity give more information than species richness alone?", options: ["It also takes into account the number of individuals of each species", "It counts only rare species", "It includes the genetic diversity of each species", "It does not need any counting"], answer: 0, explanation: "The index reflects evenness as well as the number of species." },
      { id: `q-${R}-m10`, ref: R, stmts: S(4), type: "mcq", marks: 1, stem: "Removing hedgerows reduces biodiversity mainly because it:", options: ["removes habitats, food sources, nesting sites and corridors", "increases the number of species in the fields", "raises the soil temperature", "makes the fields more even"], answer: 0, explanation: "Hedgerows supply many resources and connect habitats." },
      { id: `q-${R}-m11`, ref: R, stmts: S(4), type: "mcq", marks: 1, stem: "A farmer sprays a broad-spectrum insecticide to kill aphids. Why might this reduce biodiversity beyond the aphids?", options: ["It also kills non-target insects such as pollinators and aphid predators, and their predators lose food", "Insecticides make crops grow taller", "It only kills aphids", "It increases the number of weed species"], answer: 0, explanation: "Broad-spectrum insecticides are not specific to the pest." },
      { id: `q-${R}-m12`, ref: R, stmts: S(4), type: "mcq", marks: 1, stem: "How does growing a single crop over a large area (monoculture) reduce biodiversity?", options: ["One plant species replaces many, so there are fewer habitats and food sources", "It increases the number of plant species", "It prevents the use of fertilisers", "It always increases soil diversity"], answer: 0, explanation: "Fewer plant species means fewer niches for animals." },
      { id: `q-${R}-m13`, ref: R, stmts: S(5), type: "mcq", marks: 1, stem: "What is an agri-environment scheme?", options: ["A scheme that pays farmers to manage land in ways that benefit wildlife", "A law that bans all farming near rivers", "A method of increasing crop yields with fertilisers", "A plan to replace hedgerows with fences"], answer: 0, explanation: "Payments encourage measures such as hedgerows and margins." },
      { id: `q-${R}-m14`, ref: R, stmts: S(5), type: "mcq", marks: 1, stem: "Which statement best describes the balance between food production and conservation?", options: ["Measures that conserve biodiversity often reduce cropped area or raise costs, so decisions weigh food output against biodiversity", "Conservation measures always increase food production, so there is no cost to farmers in adopting them", "Food production has little effect on biodiversity as long as the same crop is grown each year", "Biodiversity can only be conserved on land where no farming of any kind takes place"], answer: 0, explanation: "The specification asks you to understand a balance: trade-offs, not absolutes." },
      { id: `q-${R}-m16`, ref: R, stmts: S(2, 3), type: "mcq", marks: 1, stem: `Site 1 has d = ${M.fix(dM.d)} and site 2 has d = ${M.fix(dC.d)}, both sampled the same way. Which conclusion is valid?`, options: ["Site 1 is more diverse: more species and/or more even numbers of individuals", "Site 1 has exactly 3.7 times as many species", "Site 2 contains no rare species", "Site 1 contains more individuals"], answer: 0, explanation: "A higher d means greater diversity; d does not give the number of species, individuals or which species are present." },
      { id: `q-${R}-m17`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "A student calculated d using n² instead of n(n − 1). What effect does this have?", options: ["The bottom line is too large, so the value is wrong (too small)", "No effect: n² and n(n − 1) are equal", "The value is too large", "d cannot be calculated"], answer: 0, explanation: "n² > n(n − 1) for every n ≥ 1, so the denominator is overestimated (and the top should be N(N − 1), not N²)." },
      // ---- gap fills (answers computed from B.biodivModel.index and checked by hand) ----
      { id: `q-${R}-g1`, ref: R, stmts: S(1, 2), type: "gap", marks: 3, stem: "Complete the passage.", text: "Species {{1}} is the number of different species in a community. An index of {{2}} describes the relationship between the number of species and the number of {{3}} in each species.", answers: { 1: ["richness"], 2: ["diversity"], 3: ["individuals", "organisms"] }, explanation: "Richness; diversity; individuals." },
      { id: `q-${R}-g2`, ref: R, stmts: S(3), type: "gap", marks: 3, stem: `Animals counted on a rocky shore:\n${tbl(shore.map((n, i) => [["Limpet sp.", "Periwinkle sp.", "Barnacle sp.", "Dog whelk sp.", "Shore crab sp."][i], n]))}Give d to 2 decimal places.`, text: "N = {{1}}. Σn(n − 1) = {{2}}. d = {{3}}.", answers: { 1: [String(dShore.N)], 2: [String(dShore.sigma)], 3: [M.fix(dShore.d)] }, explanation: `N = ${dShore.N}; Σ = ${dShore.terms.join(" + ")} = ${dShore.sigma}; N(N − 1) = ${dShore.top}; d = ${dShore.top} ÷ ${dShore.sigma} = ${M.fix(dShore.d)}.` },
      { id: `q-${R}-g3`, ref: R, stmts: S(3, 2), type: "gap", marks: 3, stem: `Invertebrates netted in two ponds (same method).\n${tbl([["A", 12, 30], ["B", 8, 3], ["C", 5, 2], ["D", 3, 1], ["E", 1, 0], ["F", 1, 0]], ["Species", "Pond X", "Pond Y"])}Give values of d to 2 decimal places.`, text: "d for pond X: {{1}}. d for pond Y: {{2}}. The more diverse pond is pond {{3}}.", answers: { 1: [M.fix(dPX.d)], 2: [M.fix(dPY.d)], 3: ["X"] }, explanation: `Pond X: N = ${dPX.N}, N(N − 1) = ${dPX.top}, Σ = ${dPX.terms.join(" + ")} = ${dPX.sigma}, d = ${M.fix(dPX.d)}. Pond Y: N = ${dPY.N}, N(N − 1) = ${dPY.top}, Σ = ${dPY.terms.join(" + ")} = ${dPY.sigma}, d = ${M.fix(dPY.d)}.` },
      { id: `q-${R}-g4`, ref: R, stmts: S(3), type: "gap", marks: 2, stem: "A sample has N = 21 and an index of diversity of 2.5.", text: "N(N − 1) = {{1}}. Σn(n − 1) = {{2}}.", answers: { 1: ["420"], 2: ["168"] }, explanation: "21 × 20 = 420; Σ = 420 ÷ 2.5 = 168." },
      { id: `q-${R}-g5`, ref: R, stmts: S(3, 4), type: "gap", marks: 2, stem: `Animals on the mud at a mangrove edge and on a bare sand flat (hypothetical data, five quadrats each).\n${tbl([["Fiddler crab sp.", 18, 5], ["Mud creeper snail sp.", 25, 30], ["Mudskipper sp.", 4, 0], ["Barnacle sp.", 10, 0], ["Burrowing worm sp.", 3, 2]], ["Species", "Mangrove edge", "Sand flat"])}Give values of d to 2 decimal places.`, text: "Mangrove edge: {{1}}. Sand flat: {{2}}.", answers: { 1: [M.fix(dMg.d)], 2: [M.fix(dSf.d)] }, explanation: `Mangrove: N = 60, 3540 ÷ 1014 = ${M.fix(dMg.d)}. Sand flat: N = 37, 1332 ÷ 892 = ${M.fix(dSf.d)}.` },
      // ---- matching ----
      { id: `q-${R}-mt1`, ref: R, stmts: S(1, 2, 3), type: "match", marks: 4, stem: "Match each term to its meaning.", pairs: [{ left: "Species richness", right: "The number of different species in a community" }, { left: "Community", right: "All the populations of different species in an area at the same time" }, { left: "Index of diversity", right: "Relates the number of species to the number of individuals of each" }, { left: "N in the index of diversity", right: "The total number of organisms of all species" }] },
      { id: `q-${R}-mt2`, ref: R, stmts: S(4, 5), type: "match", marks: 4, stem: "Match each farming practice to its main effect on biodiversity.", pairs: [{ left: "Removing hedgerows", right: "Loss of nesting sites, food plants and corridors between habitats" }, { left: "Broad-spectrum insecticide", right: "Kills non-target insects such as pollinators and pest predators" }, { left: "Uncropped field margins", right: "Provide habitat and food at the cost of some cropped area" }, { left: "Fertiliser run-off into a stream", right: "Eutrophication lowers oxygen and kills aquatic organisms" }] },
      // ---- data, short answer, evaluation ----
      { id: `q-${R}-s1`, ref: R, stmts: S(1, 2), type: "short", marks: 2, stem: "Explain why an index of diversity can be more useful than species richness for comparing two communities. (2 marks)", scheme: [{ point: "Species richness only counts the number of species", marks: 1 }, { point: "The index also takes into account the number of individuals of each species (evenness), so communities with the same richness can be distinguished", marks: 1 }], model: "Species richness counts only the number of different species and ignores how many individuals each has. The index of diversity also takes account of the number of individuals of each species, so a community where the individuals are spread evenly scores higher than one with the same number of species dominated by one of them.", commonErrors: "Saying the index counts more species." },
      { id: `q-${R}-s2`, ref: R, stmts: S(1, 3, 2), type: "short", marks: 5, stem: `Data. Pitfall traps in a field margin and in the cropped field caught these invertebrates (illustrative).\n${tbl(CM.margin.species.map(([nm, n]) => [nm, n, (CM.crop.species.find((x) => x[0] === nm) || [0, 0])[1]]), ["Species", "Margin", "Crop"])}(a) Give the species richness of each habitat. (1 mark) (b) Calculate the index of diversity for each habitat, showing your working. Give each value to 2 decimal places. (3 marks) (c) Compare the two habitats. (1 mark)`, scheme: [{ point: `(a) Margin ${dM.richness}; crop ${dC.richness}`, marks: 1 }, { point: `(b) Margin: N = ${dM.N}, N(N − 1) = ${dM.top}, Σn(n − 1) = ${dM.sigma}`, marks: 1 }, { point: `(b) Margin d = ${M.fix(dM.d)}`, marks: 1 }, { point: `(b) Crop: N = ${dC.N}, Σn(n − 1) = ${dC.sigma}, d = ${dC.top} ÷ ${dC.sigma} = ${M.fix(dC.d)}`, marks: 1 }, { point: "(c) The margin is more diverse: more species and individuals more evenly spread (the crop is dominated by one species)", marks: 1 }], model: `(a) Margin: ${dM.richness} species; crop: ${dC.richness} species. (b) Margin: N = ${dM.N}; N(N − 1) = ${dM.top}; Σn(n − 1) = ${dM.terms.join(" + ")} = ${dM.sigma}; d = ${dM.top} ÷ ${dM.sigma} = ${M.fix(dM.d)}. Crop: N = ${dC.N}; N(N − 1) = ${dC.top}; Σn(n − 1) = ${dC.terms.filter((t, i) => dC.ns[i] > 0).join(" + ")} = ${dC.sigma}; d = ${dC.top} ÷ ${dC.sigma} = ${M.fix(dC.d)}. (c) The margin has a much higher index: twice as many species and a more even spread of individuals, whereas in the crop one ground beetle species makes up three quarters of the catch.`, commonErrors: "Including species with zero individuals in the crop's richness; using n² or N²." },
      { id: `q-${R}-s3`, ref: R, stmts: S(3), type: "short", marks: 2, stem: "A student finds seven species in a single small quadrat, each represented by one individual, and writes 'd = 0, so this habitat has no diversity'. Explain the error and what the student should do. (2 marks)", scheme: [{ point: "Each n(n − 1) = 0 so Σn(n − 1) = 0: the formula would divide by zero, so d cannot be calculated (it is not 0)", marks: 1 }, { point: "Take a larger sample (more or larger quadrats) so that species are represented by more individuals", marks: 1 }], model: "With one individual of each species, every n(n − 1) is 1 × 0 = 0, so Σn(n − 1) = 0 and the index would require division by zero: d cannot be calculated, which is not the same as zero diversity (the sample actually has seven species). The student should take a larger sample, with more or bigger quadrats, before calculating d.", commonErrors: "Saying d is infinite or very large." },
      { id: `q-${R}-s4`, ref: R, stmts: S(4), type: "short", marks: 4, stem: "Describe and explain how two different human activities can reduce biodiversity. (4 marks)", scheme: [{ point: "Activity 1 named (e.g. clearing land / hedgerow removal / monoculture / pesticides / fertiliser run-off / overfishing / introduced species)", marks: 1 }, { point: "Mechanism for activity 1 (e.g. removes habitats, food, nesting sites; kills non-target species; eutrophication; out-competes natives)", marks: 1 }, { point: "Activity 2 named", marks: 1 }, { point: "Mechanism for activity 2, linked to fewer species or less even numbers", marks: 1 }], model: "Clearing mangroves for coastal development removes the habitat that provides food, shelter and nursery areas for many fish, invertebrates and birds, so species decline or are lost and species richness falls. Spraying broad-spectrum insecticide on crops kills non-target insects as well as pests, including pollinators and predators; the animals that feed on these insects then lose food, so populations fall and fewer species can live on the farmland.", commonErrors: "Listing activities with no mechanism; 'pollution kills animals' without detail." },
      { id: `q-${R}-s5`, ref: R, stmts: S(5, 4), type: "short", marks: 4, stem: `Evaluation. A government proposes paying farmers to leave 6 m uncropped margins round fields. In a pilot, invertebrate diversity was d = ${M.fix(dM.d)} in margins and d = ${M.fix(dC.d)} in the crop, and margins took about ${M.fix(marginPct, 1)} % of the area of a 10 ha field. Evaluate the proposal. (4 marks)`, scheme: [{ point: "Benefit: margins much more diverse (quotes the values); habitat/food for invertebrates, possibly pollinators and pest predators", marks: 1 }, { point: "Cost: cropped area / food production reduced (about the stated percentage); cost of payments", marks: 1 }, { point: "Limitation: one pilot / index does not show which species benefit / no yield data / effects may vary between farms and years", marks: 1 }, { point: "Balanced judgement, e.g. worthwhile if payments compensate for lost yield, or targeted margins next to existing habitats", marks: 1 }], model: `The pilot supports the proposal for biodiversity: margins were far more diverse (d = ${M.fix(dM.d)}) than the crop (d = ${M.fix(dC.d)}), probably because they provide habitat and food that the crop does not, possibly including pollinators and predators of crop pests. Against this, about ${M.fix(marginPct, 1)} % of each 10 ha field would no longer produce food, and the payments cost public money. The evidence is limited: it is one pilot, the index does not show which species benefit, and there are no yield data, so effects on food production are unknown. Overall the scheme seems worthwhile if payments cover lost income and its effects on yield are monitored over several years.`, commonErrors: "One-sided answers; ignoring the food-production cost." },
      { id: `q-${R}-d1`, ref: R, stmts: S(2, 3, 5), type: "short", marks: 3, stem: `Data. A farm replanted hedgerows in year 0. Bird surveys used the same method each year (illustrative).\n${tbl([["0", 6, M.fix(ix([20, 8, 5, 3, 2, 1]).d)], ["2", 8, M.fix(ix([18, 9, 7, 5, 4, 3, 2, 1]).d)], ["5", 11, M.fix(ix([15, 10, 8, 7, 6, 5, 4, 3, 2, 2, 1]).d)]], ["Year", "Species richness", "Index of diversity"])}(a) Describe the change. (1 mark) (b) A student concludes that 'replanting hedgerows increases bird diversity on farms'. Evaluate this conclusion. (2 marks)`, scheme: [{ point: "(a) Both species richness and the index of diversity increased over the five years", marks: 1 }, { point: "(b) Supports the conclusion for this farm: diversity rose after replanting", marks: 1 }, { point: "(b) But one farm, no control farm without replanting / other factors (weather, neighbouring land) could explain it; cannot generalise to all farms", marks: 1 }], model: `(a) Species richness rose from 6 to 11 and the index of diversity from ${M.fix(ix([20, 8, 5, 3, 2, 1]).d)} to ${M.fix(ix([15, 10, 8, 7, 6, 5, 4, 3, 2, 2, 1]).d)}. (b) The data are consistent with replanting increasing bird diversity on this farm. However, there is only one farm and no comparison farm without new hedgerows, so other changes over the five years (weather, nearby land use, regional trends) could explain the rise; the conclusion cannot be applied to all farms without replicated studies.`, commonErrors: "Accepting the conclusion without considering a control." },
      // ---- decision scenarios: food production and conservation ----
      ...scenarioQs,
      // ---- extended ----
      { id: `q-${R}-e1`, ref: R, stmts: S(4, 5), type: "extended", marks: 6, stem: "Extended response. Discuss how farming can reduce biodiversity, and how a balance can be achieved between food production and conservation. (6 marks)", scheme: [{ point: "Hedgerow removal / larger fields: loss of habitats, food, nesting sites, corridors", marks: 1 }, { point: "Monoculture and herbicides: fewer plant species, fewer niches and food sources", marks: 1 }, { point: "Insecticides kill non-target species; fertiliser run-off causes eutrophication", marks: 1 }, { point: "Conservation measures: hedgerows kept or replanted, field margins, set-aside, crop rotation, targeted pesticide use", marks: 1 }, { point: "Agri-environment schemes pay farmers to compensate for lost yield or extra costs", marks: 1 }, { point: "Trade-off made explicit: measures reduce cropped area or yield / cost money; a balance means enough food with as much biodiversity as possible, judged with evidence", marks: 1 }], levels: "Level 3 (5–6): at least two farming practices with mechanisms, at least two conservation measures, and a clear discussion of the trade-off. Level 2 (3–4): practices and measures described, trade-off implied. Level 1 (1–2): a list with little explanation.", model: "Intensive farming increases food production per hectare but tends to reduce biodiversity. Removing hedgerows to make large fields removes habitats, nesting sites and food such as berries and insects, and breaks the corridors that let animals move between habitats. Growing one crop over large areas, with herbicides to remove weeds, leaves few plant species and so few niches and food sources for animals. Broad-spectrum insecticides kill non-target insects such as pollinators and predators of pests, and fertiliser run-off can cause eutrophication of rivers and lakes. A balance can be achieved by keeping and replanting hedgerows, leaving uncropped field margins, setting some land aside, rotating crops, and spraying only when pests reach a threshold. Each measure has a cost: less land is cropped, yields may fall, or management takes more time and money. Agri-environment schemes pay farmers to offset these costs. The best balance depends on evidence from each farm, such as yields and measures of diversity over several years, so that enough food is produced while as much biodiversity as possible is retained.", commonErrors: "Describing only the harm or only the solutions; no explicit trade-off." },
      { id: `q-${R}-e2`, ref: R, stmts: S(1, 3, 2), type: "extended", marks: 6, stem: "Extended response. Describe how you could compare the species diversity of animals on the mud at a mangrove edge with that on a nearby bare sand flat at low tide. Include how you would collect the data, calculate the index of diversity and interpret the results. (6 marks)", scheme: [{ point: "Quadrats of the same size placed at random coordinates (e.g. random-number grid) in each habitat", marks: 1 }, { point: "Same number of quadrats, same tidal state / time of day and season at both sites", marks: 1 }, { point: "Identify each organism to species and count the individuals of each species (n) in every quadrat; pool the counts for each habitat", marks: 1 }, { point: "Calculate N and n(n − 1) for each species; Σn(n − 1); d = N(N − 1) ÷ Σn(n − 1)", marks: 1 }, { point: "Higher d = more diverse; compare richness as well; d depends on richness and evenness", marks: 1 }, { point: "Limitation / caution: enough quadrats to be representative; d cannot be calculated if Σ = 0; one survey; safety and minimal disturbance (supporting)", marks: 1 }], levels: "Level 3 (5–6): valid, controlled sampling in both habitats, a correct description of the calculation, and a reasoned interpretation with a limitation. Level 2 (3–4): sampling and calculation described with gaps. Level 1 (1–2): fragments.", model: "At low tide on the same day, lay out a grid over each habitat and use random numbers to choose coordinates for, say, ten 0.25 m² quadrats in each. In every quadrat, identify each animal on the mud surface to species and count the individuals of each species, then add the counts for each habitat. For each habitat find N, calculate n(n − 1) for every species, add these to give Σn(n − 1), calculate N(N − 1) and divide to give d. The habitat with the higher d is more diverse, because it has more species, a more even spread of individuals, or both; species richness can be compared too. Enough quadrats should be used that extra ones add few new species, and if every species were found only once d could not be calculated, so a larger sample would be needed. One survey gives a snapshot; repeating on other days would show whether the difference is consistent.", commonErrors: "Placing quadrats where organisms are visible (bias); different numbers of quadrats at each site." },
    ],
  };
})();
